class FixedTimeStepGameLoop {
  constructor(update, render, fps = 60) {
    this.update = update;
    this.render = render;
    this.timestep = 1000 / fps; // 毫秒
    this.lastTime = 0;
    this.accumulator = 0;
    this.currentTime = 0;
  }run(timestamp) {
    // 计算自上一帧的时间
    let deltaTime = timestamp - this.lastTime;
    this.lastTime = timestamp;// 防止螺旋死亡（spiral of death）
    deltaTime = Math.min(deltaTime, this.timestep * 5);this.accumulator += deltaTime;

// 固定时间步长更新
    while (this.accumulator >= this.timestep) {
      this.update(this.timestep / 1000); // 转换为秒
      this.currentTime += this.timestep;
      this.accumulator -= this.timestep;
    }// 插值渲染
    const interpolation = this.accumulator / this.timestep;
    this.render(interpolation);requestAnimationFrame((time) => this.run(time));
  }start() {
    this.lastTime = performance.now();
    this.currentTime = 0;
    this.accumulator = 0;
    requestAnimationFrame((time) => this.run(time));
  }
}
